"""Build the inspectable local QA gallery from saved evidence, without dependencies."""
import hashlib
import html
import json
import pathlib

B = pathlib.Path(__file__).resolve().parent
ROOT = B.parents[2]
read = lambda p: json.loads((B / p).read_text(encoding='utf-8-sig'))
groups = {name: read(name + '/proof.json') for name in ['after-day-en', 'after-day-ar', 'after-night-en', 'final-home', 'controls-final']}
assert len(groups['after-day-en']['frames']) == 28
assert len(groups['after-day-ar']['frames']) == 14
assert len(groups['after-night-en']['frames']) == 14
assert len(groups['final-home']['frames']) == 12
refs = [r for r in read('reference-manifest.json')['references'] if r['section'] != 'settings-duplicate']
names = dict(studio='Organization Studio', home='Home', workspace='Google Workspace', startup='Startup', smart_scan='Smart Scan', applications='Applications', services='Services', system='System', repair='Repair', automation='Automation', files='Files', storage='Storage', cleanup='Cleanup', settings='Settings')
gaps = dict(studio='Floating folder stack, five-stage reference composition and shared shell reconciliation remain open.', home='New Welcome to KNOuX composition differs from existing Command Center. Keep genuine measurements and working body.', workspace='Floating branded Google tiles and large Google hub arrangement remain absent. Preserve real OAuth/scopes.', startup='Windows/settings glass artwork and capsule workflow remain absent. No fabricated 50% progress.', smart_scan='Reference bilingual spacing, glass documents and three satellites need composition work.', applications='Floating app/media artwork and distinct pipeline remain open; do not imply unimplemented deployment.', services='Luminous mesh, Commander hub and orchestration composition remain absent.', system='System Performance skyline/chart artwork differs from existing Observatory. Keep real measured charts.', repair='Seven-stage arrangement and reference satellites differ; keep existing SFC/DISM/restore safeguards.', automation='Workflow artwork/composition remains open. Short screens start in focused editor; Show overview works.', files='Folder-stack artwork remains absent. Tool/table overlap repair verified through fixture search/scroll/selection.', storage='Server-stack artwork and reference pipeline placement differ. Keep native volume and scope controls.', cleanup='Glowing bin/floating file artwork remains absent. Closed scope disclosure is intentional; expansion tested.', settings='Floating preference panels, six-stage reference pipeline and Settings Center composition remain open.')
frames = []
for group, proof in groups.items():
    for f in proof.get('frames', []):
        f = dict(f, group=group)
        frames.append(f)
def pick(section, theme='day', locale='en', width=1672):
    candidates = [f for f in frames if f['section'] == section and f['theme'] == theme and f['locale'] == locale and f['width'] == width]
    return candidates[-1]
rows = []
for ref in refs:
    s = ref['section']; f = pick(s); state = f['state']; scenarios = {}
    for label, theme, locale, width in [('Day 1672','day','en',1672), ('Day 1920','day','en',1920), ('RTL 1366','day','ar',1366), ('Night 1672','night','en',1672)]:
        item = pick(s, theme, locale, width)
        stem = item['screenshot'][:-4]
        scenarios[label] = {'image': item['group'] + '/' + item['screenshot'], 'body': item['group'] + '/' + stem + '-body-end.png', 'bodyExists': (B / item['group'] / (stem + '-body-end.png')).exists(), 'hero': item['state'].get('hero'), 'viewport': item['state']['viewport']}
    baseline_group = 'baseline-settings' if s == 'settings' else 'baseline'
    scenarios['Before repair'] = {'image': f'{baseline_group}/{s}-day-en-1672x941.png', 'bodyExists': False, 'hero': None, 'viewport': {'width':1672,'height':941}}
    rows.append({'section':s,'name':names[s],'reference':f'references/{s}.png','gap':gaps[s],'scenarios':scenarios,'geometry':state.get('hero')})
geometry = [{'section':r['section'], **(r['geometry'] or {})} for r in rows]
(B / 'section-audit.json').write_text(json.dumps(rows, ensure_ascii=False, indent=2), encoding='utf-8')
errors = sum(len(g.get('errors', [])) for g in groups.values())
requests = sum(len(g.get('failedRequests', [])) for g in groups.values())
console_messages = sorted(set(x['message'] for g in groups.values() for x in g.get('consoleErrors', [])))
controls = groups['controls-final']
final_hashes = read('source-fingerprint-final.json')
drift = [r['path'] for r in final_hashes if not (ROOT / r['path']).is_file() or hashlib.sha256((ROOT / r['path']).read_bytes()).hexdigest() != r['sha256']]
stability = {'checkedFiles':len(final_hashes),'changed':drift,'stable':not drift,'scope':'source-fingerprint-final.json; general matrix predates Home-only repair, final-home supersedes Home frames; see source-evolution.json'}
(B/'source-stability.json').write_text(json.dumps(stability,indent=2),encoding='utf-8')
checks = read('final-check-results.json')
initial = read('check-results.json')
qa = ['# Visual fidelity QA — 2026-11-02', '', '**PARTIALLY VERIFIED. No section is visually accepted against the new references.**', '', '## Reality and preservation', '', '- Starting and directly queried remote main: `8871103c7fd2a274a70fe2a069bb435f2ccb12ac`.', '- 769 initial dirty/untracked paths copied outside the repository with SHA-256 verification; 383,015,386 bytes; no original path missing.', '- Original Qoder/owner work remains in `D:\\KNOUX-Workspace\\KNOuX_VISUAL_HANDOFF_CHECKPOINT_20261102-151606`. It is a file checkpoint, not a commit.', '', '## Actual runtime evidence', '', '- Production dist in disposable Electron profiles, actual Main + Preload + Renderer. This is not an installed-package or production deployment test.', '- 56 route/theme/locale/viewport matrix states: all fourteen Day EN at 1672×941 and 1920×1080, Day AR/RTL at 1366×768, Night EN at 1672×941.', '- 12 additional Home states cover EN/AR × Day/Night × all three sizes after its narrowly scoped orbit fit repair. These supersede earlier Home frames.', f'- Uncaught renderer errors: {errors}. Failed requests/HTTP errors observed: {requests}.', '- Existing console diagnostic retained: meta-delivered CSP frame-ancestors is ignored. No “zero console errors” claim.', f'- Final source stability: {len(final_hashes)} files checked; changed files during final capture: {len(drift)}.', '- No owner folder authorization, file open/move/delete, Registry/SCM/startup change, account connection or workflow execution occurred during these visual probes.', '', '## Focused interactions', '']
for r in controls['results']:
    qa.append(f"- `{r['name']}`: {'VERIFIED' if r['ok'] else 'FAILED'}" + ('.' if r['ok'] else ': '+r['error']))
qa += ['', 'Files search/filtering and final-row selection are explicitly built-in **fixture UI** checks; they do not certify an owner-folder index. Both EN/AR short-window runs verified visible footer, nonzero result area, no tool/table overlap, last-row hit testing and no document scrolling.', '', '## Measurement corrections', '', '- Baseline Settings timeout was a harness selector defect: Appearance-only `settings-theme` was replaced with route-level `settings-root`; corrected baseline capture is preserved separately.', '- Initial Cleanup “six controls below hero” numbers count children of a closed `<details>` disclosure. They are not visible clipping. Focused probe verifies closed visibility and opening/category controls. Final harness uses `Element.checkVisibility`.', '- Automation hero is intentionally hidden in short-height editor focus mode. The existing Show overview action was exercised and its real screenshot retained in `controls-final/automation-show-overview-ar-1366.png`.', '- The first focused Cleanup probe selected its inner div instead of the details element. Its failed assertion is retained in `controls/proof.json`; corrected selector and rerun are in `controls-final/proof.json`.', '- Reference/runtime images have different framing/aspect ratios and are displayed without stretching. No pixel score or pixel-perfect claim is made.', '', '## Equal bounds gate — OPEN', '', '| Section | x | y | width | height |', '|---|---:|---:|---:|---:|']
for g in geometry:
    qa.append('| '+names[g['section']]+' | '+' | '.join(str(round(g.get(k,0),1)) for k in ['x','y','w','h'])+' |')
qa += ['', 'Actual Day EN geometry at the common 1672×941 content viewport still varies. Shared minimums prevent clipping but do not satisfy equal width/height/top offset. Studio shell remains separate. All section-specific artwork/composition/body-fidelity items in `section-audit.json` remain OPEN.', '', '## Engineering checks', '', '| Command from apps/gemini-ui | Result |', '|---|---|']
for r in checks: qa.append(f"| `npm run {r['check']}` | exit {r['exitCode']} |")
qa += ['', 'Earlier successful initial checks also include `test:i18n`, `test:home`, `test:navigation`, `test:workbench`, and `test:native`; full logs are preserved. Initial `test:theme` failed on role parity, then passed after repair (12/12 plus generated material bridge). Home follow-up reran theme, TypeScript and build successfully. The complete package test suite and installed app were not executed.', '', '## Delivery', '', '- Modified locally on main; scoped source repair and evidence/handoff artifacts created.', '- No staging, commit, push, PR creation/merge or deployment by this mission.', '- Existing main CI is successful at the starting SHA only; dirty source is covered by local checks, not that CI.', '- Existing PR #4 remains open and its six unique donor commits remain preserved; no blind merge.', '- Next: reconcile shell/header boundaries, establish equal Day bounds, then implement each distinct matching reference and whole-route continuity while retaining real actions. Follow `docs/handoffs/VISUAL_FIDELITY_CODEX_20261102.md`.']
(B/'QA_SUMMARY.md').write_text('\n'.join(qa)+'\n',encoding='utf-8')
data=json.dumps(rows,ensure_ascii=False).replace('</','<\\/')
cards=[]
for r in rows:
    cards.append(f'''<article id="{r['section']}"><h2>{html.escape(r['name'])} <small>OPEN · fidelity not accepted</small></h2><p>{html.escape(r['gap'])}</p><div class="pair"><figure><figcaption>المرجع المعتمد · 2172×724</figcaption><a href="{r['reference']}" target="_blank"><img loading="lazy" src="{r['reference']}" alt="{r['name']} approved reference"></a></figure><figure><figcaption class="actual-label">Electron · Day EN 1672×941</figcaption><a class="actual-link" href="{r['scenarios']['Day 1672']['image']}" target="_blank"><img class="actual" loading="lazy" src="{r['scenarios']['Day 1672']['image']}" alt="{r['name']} actual runtime"></a><a class="body-link" href="{r['scenarios']['Day 1672']['body']}" target="_blank">صورة نهاية المحتوى الداخلي</a><pre class="geometry"></pre></figure></div></article>''')
page='''<!doctype html><html lang="ar"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>KNOuX — Reference / runtime evidence</title><style>*{box-sizing:border-box}body{margin:0;background:#f6f3ff;color:#20163d;font:15px/1.6 system-ui,sans-serif}header{padding:22px 30px;background:#fff;border-bottom:1px solid #d9cdf4}header p{max-width:1100px}h1{margin:8px 0;font-size:25px}.warning{padding:12px;border-inline-start:4px solid #955fe0;background:#f2eaff}nav{position:sticky;top:0;background:#fffc;backdrop-filter:blur(12px);padding:12px 25px;z-index:3;border-bottom:1px solid #d9cdf4;display:flex;gap:12px;flex-wrap:wrap}select{padding:8px;border:1px solid #aa8ad4;border-radius:8px;background:#fff;font:inherit}main{padding:16px 25px}article{background:white;border:1px solid #dbd0f0;border-radius:14px;margin:0 0 24px;padding:18px}h2{font-size:22px;margin:0}small{font-size:12px;color:#875721;font-weight:500}p{margin:8px 0}.pair{display:grid;grid-template-columns:1fr 1fr;gap:18px}figure{margin:0;min-width:0}figcaption{font-weight:650;margin:8px 0}img{display:block;width:100%;height:auto;border:1px solid #d2c4eb}a{color:#6531b0}pre{font-size:12px;white-space:pre-wrap;direction:ltr}.links{display:flex;gap:18px;flex-wrap:wrap}@media(max-width:1000px){.pair{grid-template-columns:1fr}}</style><header><div dir="rtl">بسم الله والصلاة والسلام علي رسول الله صلي الله عليه وسلم</div><h1>KNOuX SmartOrganizer · المرجع مقابل التشغيل الفعلي</h1><p class="warning" dir="rtl">الحالة: PARTIALLY VERIFIED. الصور أدلة تشغيل، وليست موافقة على المطابقة. تم حفظ الشغل السابق وإصلاح قصّ عناصر التحكم. توحيد الحدود والرسومات المميزة لكل قسم واستمرارية الصفحة لسه مطلوبين.</p><p dir="rtl">كل صورة مرجع محفوظة بأبعادها الأصلية، وصور Electron بأبعاد التشغيل الفعلية. المقارنة معروضة بدون تمديد أو ادعاء تطابق بكسلي. اختيار Before يعرض التنفيذ قبل الإصلاح.</p><div class="links"><a href="QA_SUMMARY.md">التقرير والأرقام</a><a href="reference-manifest.json">بصمات المراجع</a><a href="preservation.json">النسخة الاحتياطية</a><a href="../../handoffs/VISUAL_FIDELITY_CODEX_20261102.md">Codex handoff</a><a href="controls-final/proof.json">فحص التفاعلات</a></div></header><nav><label>عرض التشغيل <select id="scenario"><option>Day 1672</option><option>Day 1920</option><option>RTL 1366</option><option>Night 1672</option><option>Before repair</option></select></label><label>القسم <select id="jump"><option value="">كل الأقسام</option>OPTIONS</select></label></nav><main>CARDS</main><script>const rows=DATA;function update(){for(const row of rows){const article=document.getElementById(row.section),s=row.scenarios[document.getElementById('scenario').value];article.querySelector('.actual').src=s.image;article.querySelector('.actual-link').href=s.image;article.querySelector('.actual-label').textContent='Actual Electron · '+document.getElementById('scenario').value;const body=article.querySelector('.body-link');body.hidden=!s.bodyExists;if(s.bodyExists)body.href=s.body;article.querySelector('.geometry').textContent=s.hero?'Measured hero bounds: '+JSON.stringify(s.hero):'';}}document.getElementById('scenario').onchange=update;document.getElementById('jump').onchange=e=>{if(e.target.value)document.getElementById(e.target.value).scrollIntoView({block:'start'});};update();</script></html>'''
page=page.replace('OPTIONS',''.join(f'<option value="{r["section"]}">{r["name"]}</option>' for r in rows)).replace('CARDS',''.join(cards)).replace('DATA',data)
(B/'index.html').write_text(page,encoding='utf-8')
print(json.dumps({'gallery':str(B/'index.html'),'sections':len(rows),'matrixStates':56,'homeFollowups':12,'controlsOk':controls['ok'],'sourceStable':not drift,'uncaughtErrors':errors,'failedRequests':requests,'consoleMessages':console_messages},indent=2))
